function locationString(location) {
  if (!location) return '';
  return [location.city, location.region, location.countryCode]
    .filter(Boolean)
    .join(', ');
}

function SectionHeader({ no, title }) {
  return (
    <SectionHead>
      <PartNo>{no}</PartNo>
      <SectionTitle>{title}</SectionTitle>
      <DimLine aria-hidden="true" />
    </SectionHead>
  );
}

